script:
// ===== 7 EPG EK SATH - HK1 SG1 IN1 IN2 IN4 UK1 US2 =====
let EPG_URLS = [
  "https://epgshare01.online/epgshare01/epg_ripper_HK1.xml.gz",
  "https://epgshare01.online/epgshare01/epg_ripper_SG1.xml.gz",
  "https://epgshare01.online/epgshare01/epg_ripper_IN1.xml.gz",
  "https://epgshare01.online/epgshare01/epg_ripper_IN2.xml.gz",
  "https://epgshare01.online/epgshare01/epg_ripper_IN4.xml.gz",
  "https://epgshare01.online/epgshare01/epg_ripper_UK1.xml.gz",
  "https://epgshare01.online/epgshare01/epg_ripper_US2.xml.gz"
];

async function autoDownloadAll(){
  document.getElementById('status').innerText = "📡 7 EPG Download Ho Rahe Hai... HK1 SG1 IN1 IN2 IN4 UK1 US2";

  let results = await Promise.all(
    EPG_URLS.map(async (url) => {
      try{
        let res = await fetch(url);
        let txt = "";
        if(url.endsWith(".gz")){
          let buf = await res.arrayBuffer();
          let ds = new DecompressionStream('gzip');
          let decompressed = new Response(new Blob([buf]).stream().pipeThrough(ds));
          txt = await decompressed.text();
        } else {
          txt = await res.text();
        }
        let data = parseXML(txt);
        console.log("✅ Ho Gaya:", url, data.length + " channels");
        return data;
      }catch(e){
        console.log("❌ Fail:", url);
        return [];
      }
    })
  );

  // 7 KA DATA MILAO - DUPLICATE HATAO
  let merged = [];
  results.forEach(list => {
    list.forEach(ch => {
      let already = merged.find(m => m.name == ch.name);
      if(!already) merged.push(ch);
      else already.shows = [...already.shows, ...ch.shows];
    });
  });

  allData = merged;
  document.getElementById('status').innerText = "✅ 7 EPG Mil Gaye Sir - Total " + allData.length + " Channels";
  render();
}

function parseXML(txt){
  let parser = new DOMParser();
  let xml = parser.parseFromString(txt,"text/xml");
  let out = [];
  xml.querySelectorAll("channel").forEach(ch=>{
    let id = ch.getAttribute("id");
    let name = ch.querySelector("display-name")?.textContent || id;
    let progs = [...xml.querySelectorAll(`programme[channel="${id}"]`)].slice(0,4).map(p=>({
      t: p.getAttribute("start")?.slice(8,10)+":"+p.getAttribute("start")?.slice(10,12),
      d: p.querySelector("title")?.textContent || "Show",
      w: 140
    }));
    if(progs.length==0) progs=[{t:"Now",d:"Live Show",w:200}];
    out.push({id:id.slice(-3), name:name, cat:"entertainment", lang:"hindi", shows:progs});
  });
  return out;
}

autoDownloadAll();
setInterval(autoDownloadAll, 30*60*1000);
